import{_ as r,a0 as l,w as p,s as u,ao as i,I as a,x as e,a1 as o,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const N=JSON.parse('{"title":"在你的 Linux KDE 桌面上粘貼便籤 | LCTT x X-CMD","titleTemplate":false,"description":"在你的 Linux KDE 桌面上粘貼便籤 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在你的 Linux KDE 桌面上粘貼便籤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在你的 Linux KDE 桌面上粘貼便籤 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220228 Put sticky notes on your Linux KDE desktop","title":"在你的 Linux KDE 桌面上粘貼便籤","tag":"202203","desc":""},"relativePath":"202203/20220228 Put sticky notes on your Linux KDE desktop.md","filePath":"[post].md"}'),d={name:"202203/20220228 Put sticky notes on your Linux KDE desktop.md"};function m(f,t,k,K,x,b){const s=l("Link");return p(),u("div",null,[t[20]||(t[20]=i('<h1 id="在你的-linux-kde-桌面上粘貼便籤" tabindex="-1">在你的 Linux KDE 桌面上粘貼便籤 <a class="header-anchor" href="#在你的-linux-kde-桌面上粘貼便籤" aria-label="Permalink to “在你的 Linux KDE 桌面上粘貼便籤”">​</a></h1><blockquote><p>使用 Kontact 套件的功能 KNotes 温和地提醒你自己的日常任務。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202203/11/083349wujq4dbh6ccqb5kq.jpg" alt=""></p><p>我記得我第一次參加一個“不算會議的”會議，起初這是一個混亂的活動，有很多社交和個人項目的分享，但它逐漸凝聚成一個主要是自發組織的技術活動。這一切並沒有用魔法，而用的是便籤。人們在那些彩色的粘性記事貼上寫下演講和演示的想法，並將它們貼在共同的牆上，其他人將類似的想法分組，最終每個人都知道聚集在哪裏討論特定的話題。這是一件美好而令人滿意的見證，它讓我對便籤有了新的認識。所以我很高興最近發現 KDE Plasma 桌面有了數字便籤，而且在很多方面它們甚至比實體的更有用。該應用叫做 KNotes，如果你有隨意的想法想記下來，那麼你可能想在自己的 Linux 桌面貼上它。</p><h3 id="安裝-knotes" tabindex="-1">安裝 KNotes <a class="header-anchor" href="#安裝-knotes" aria-label="Permalink to “安裝 KNotes”">​</a></h3><p>KNotes 是 Kontact 套件的一部分，這是 KDE 的個人信息管理器（PIM）。如果你正在運行 Plasma 桌面，那麼你可能已經安裝了 KNotes。如果沒有，你可以從包管理器安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install kontact</span></span></code></pre></div><p>在基於 Debian 的發行版上，使用 <code>apt</code> 命令而不是 <code>dnf</code>。</p><h3 id="linux-桌面上的-knotes" tabindex="-1">Linux 桌面上的 KNotes <a class="header-anchor" href="#linux-桌面上的-knotes" aria-label="Permalink to “Linux 桌面上的 KNotes”">​</a></h3><p>儘管 KNotes 是 Kontact 的一部分，但它也是一個可以在後台運行的獨立應用，隨時可以在你需要時生成空白便籤。從你的應用菜單啓動 KNotes，它會將自身最小化到你的系統托盤。它的圖標是一個黃色的小方塊，因為在便籤在現實生活中變得豐富多彩之前，它們往往都是黃色的。</p><p>要創建新便籤，請右鍵單擊系統托盤中的 KNote 圖標並選擇 “<ruby>新便籤<rt>New Note</rt></ruby>”。第一次創建便籤時，系統會提示你選擇保存的位置。選擇本地 KNotes 資料庫文件（它由 Kontact 管理，因此你不會直接與該文件交互）並默認使用此位置。之後就不會再收到這種提示。</p><p>你的桌面上會出現一個新便籤，你可以自己在其中輸入。</p><p><img src="https://opensource.com/sites/default/files/knote-yellow.jpg" alt="Start using KNotes" title="Start using KNotes"></p><p>就這麼簡單。至少它可以像這種老式的紙質便籤一樣。但這些是數字版的 KDE KNotes，因此你可以做的不僅僅是記下一些提醒文本給自己。</p><h3 id="更改便籤顏色" tabindex="-1">更改便籤顏色 <a class="header-anchor" href="#更改便籤顏色" aria-label="Permalink to “更改便籤顏色”">​</a></h3><p>當一堆黃色便籤開始混合在一起，你可以對便籤進行顏色編碼。右鍵單擊便籤的標題欄（帶有日期和時間的部分），然後從出現的上下文菜單中選擇 “<ruby>首選項<rt>Preferences</rt></ruby>”。在該窗口中，你可以更改標題和正文字體和字體大小，然後選擇 “<ruby>顯示設置<rt>Display Settings</rt></ruby>” 選項卡以更改便籤紙和字體的顏色。</p><p><img src="https://opensource.com/sites/default/files/knote-color.jpg" alt="KNotes with added color" title="KNotes with added color"></p><h3 id="發送便籤" tabindex="-1">發送便籤 <a class="header-anchor" href="#發送便籤" aria-label="Permalink to “發送便籤”">​</a></h3>',18)),a("p",null,[t[2]||(t[2]=e("以前自己寫便籤的時候，經常會在 ",-1)),o(s,{href:"https://opensource.com/downloads/emacs-cheat-sheet"},{default:n(()=>[...t[0]||(t[0]=[e("Emacs",-1)])]),_:1}),t[3]||(t[3]=e(" 的暫存緩衝區中給自己寫一些提醒。有更好的方法來管理 ",-1)),o(s,{href:"https://opensource.com/article/18/7/emacs-modes-note-taking"},{default:n(()=>[...t[1]||(t[1]=[e("Emacs 中的便籤",-1)])]),_:1}),t[4]||(t[4]=e("，但是我將便籤內容記下後，之後心不在焉地關閉而沒保存的習慣很難改掉。",-1))]),t[21]||(t[21]=i('<p>有了 KNotes，便籤會自動保存到 Kontact，因此你不必擔心需要記着它們。更好的是，它們是數字的，因此你可以將它們發送給自己的其他設備。你可以通過電子郵件將便籤發送給自己，也可以通過網絡將它們發送到另一台計算機。只需右鍵單擊便籤的標題欄，你就可以選擇“<ruby>電子郵件<rt>Email</rt></ruby>”或“<ruby>發送<rt>Send</rt></ruby>”。</p><p>要從一個到另一個 KDE Plasma 桌面以 KNotes 方式接收便籤，你必須在接收機器上授予 KNotes 接收便籤的權限。要允許傳入便籤，請右鍵單擊系統托盤中的 KNotes 圖標並選擇 “<ruby>配置 Knotes<rt>Configure KNotes</rt></ruby>”。</p><p><img src="https://opensource.com/sites/default/files/knotes-preferences.jpg" alt="Configure KNotes" title="Configure KNotes"></p><h3 id="設置鬧鐘" tabindex="-1">設置鬧鐘 <a class="header-anchor" href="#設置鬧鐘" aria-label="Permalink to “設置鬧鐘”">​</a></h3><p>至少對我來説，寫便籤通常是因為我答應了某人的事情，通常是在短期內，比如一天結束之前。隨着我的工作和打開越來越多的窗口，貼在桌面上的便籤往往會被掩蓋，所以 KNotes 允許你為真正重要的便籤設置鬧鐘，這一點特別有用。</p><p>要為便籤設置鬧鐘，請右鍵單擊便籤的標題欄並選擇 “<ruby>設置鬧鐘<rt>Set alarm</rt></ruby>”。</p><h3 id="在-linux-上做便籤" tabindex="-1">在 Linux 上做便籤 <a class="header-anchor" href="#在-linux-上做便籤" aria-label="Permalink to “在 Linux 上做便籤”">​</a></h3><p>便箋是記錄日常任務的簡單而有趣的方法。它們不是對每個人都“有效”，也不是我跟蹤每天要做的事情的唯一手段，但它們是很好的選擇，而且在一天結束時，在刪除已完成的便籤前將它們移到“已完成”那一堆，沒有什麼比這更令人心滿意足的了。試一試吧，這是個可能能堅持下去的習慣。</p><hr>',9)),a("p",null,[t[6]||(t[6]=e("via: ",-1)),o(s,{href:"https://opensource.com/article/22/2/sticky-notes-linux-kde"},{default:n(()=>[...t[5]||(t[5]=[e("https://opensource.com/article/22/2/sticky-notes-linux-kde",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=e("作者：",-1)),o(s,{href:"https://opensource.com/users/seth"},{default:n(()=>[...t[7]||(t[7]=[e("Seth Kenlon",-1)])]),_:1}),t[12]||(t[12]=e(" 選題：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[8]||(t[8]=[e("lujun9972",-1)])]),_:1}),t[13]||(t[13]=e(" 譯者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:n(()=>[...t[9]||(t[9]=[e("geekpi",-1)])]),_:1}),t[14]||(t[14]=e(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:n(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[17]||(t[17]=e("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[15]||(t[15]=[e("LCTT",-1)])]),_:1}),t[18]||(t[18]=e(" 原創編譯，",-1)),o(s,{href:"https://linux.cn/"},{default:n(()=>[...t[16]||(t[16]=[e("Linux中國",-1)])]),_:1}),t[19]||(t[19]=e(" 榮譽推出",-1))])])}const y=r(d,[["render",m]]);export{N as __pageData,y as default};
